        { id: "jc-7-2", question: "Which method must be overridden when implementing the `Comparable` interface?", options: ["compare()", "compareTo()", "sort()", "equals()"], answerIndex: 1, explanation: "e.g., `public int compareTo(Employee other)`." },
        { id: "jc-7-3", question: "What should `a.compareTo(b)` return if object 'a' is considered GREATER than object 'b'?", options: ["A negative integer", "Zero", "A positive integer", "A boolean true"], answerIndex: 2, explanation: "Negative means smaller, zero means equal, positive means greater." },
        { id: "jc-7-4", question: "Which interface is used to define multiple, separate sorting strategies OUTSIDE of the object's class?", options: ["Comparable", "Comparator", "Sorter", "Sequence"], answerIndex: 1, explanation: "`java.util.Comparator` allows you to create classes or lambdas representing specific rules (like 'Sort By Age' or 'Sort By Name')." },
        { id: "jc-7-5", question: "Which method must be implemented for the `Comparator` interface?", options: ["compareTo(T obj)", "sort(T o1, T o2)", "compare(T o1, T o2)", "evaluate()"], answerIndex: 2, explanation: "The `compare` method takes two objects to compare against each other." },
        { id: "jc-7-6", question: "How do you sort an `ArrayList` in Java 8+?", options: ["Collections.sort(list)", "list.sort(Comparator c)", "Both A and B", "Arrays.sort(list)"], answerIndex: 2, explanation: "Java 8 added the `sort()` method directly to the `List` interface for convenience." },
        { id: "jc-7-7", question: "If you call `Collections.sort(list)` without providing a Comparator, what is required?", options: ["The list must be integers", "The elements in the list MUST implement the `Comparable` interface", "The list must be a LinkedList", "It sorts by memory address"], answerIndex: 1, explanation: "If the elements are not Comparable, the code will fail to compile (or throw a ClassCastException in older Java)." },
        { id: "jc-7-8", question: "What sorting algorithm does `Collections.sort()` use under the hood in modern Java?", options: ["QuickSort", "BubbleSort", "Timsort (a hybrid of Merge Sort and Insertion Sort)", "HeapSort"], answerIndex: 2, explanation: "Timsort guarantees O(n log n) performance and is a 'stable' sort." },
        { id: "jc-7-9", question: "What does it mean that Java's collection sorting is 'Stable'?", options: ["It never crashes", "Equal elements will preserve their original relative order from before the sort", "It uses the same amount of memory", "It sorts arrays instantly"], answerIndex: 1, explanation: "If you sort by Last Name, and then sort by First Name, people with the same First Name will remain sorted by their Last Name." },
        { id: "jc-7-10", question: "How can you reverse a `Comparator` easily in Java 8?", options: ["Create a new class", "Multiply by -1", "Use the `.reversed()` default method on the Comparator", "Use Collections.reverse()"], answerIndex: 2, explanation: "e.g., `Comparator.comparing(User::getAge).reversed()`." },
        { id: "jc-7-11", question: "How do you chain multiple Comparators together in Java 8 (e.g., Sort by Last Name, then by First Name)?", options: ["Use an if-else statement", "Use the `.thenComparing()` default method", "Add them together", "Pass an array of Comparators"], answerIndex: 1, explanation: "e.g., `Comparator.comparing(User::getLastName).thenComparing(User::getFirstName)`." },
        { id: "jc-7-12", question: "Which method creates a Comparator that handles null values gracefully, pushing nulls to the end of the list?", options: ["Comparator.nullsLast()", "Comparator.ignoreNulls()", "Comparator.safe()", "Comparator.pushNulls()"], answerIndex: 0, explanation: "e.g., `Comparator.nullsLast(Comparator.naturalOrder())` prevents NullPointerExceptions during sorting." },
        { id: "jc-7-13", question: "What is `Collections.reverseOrder()`?", options: ["It reverses a list", "A utility method that returns a Comparator which reverses the natural ordering of objects", "It reverses a string", "It sorts descending by length"], answerIndex: 1, explanation: "Pass this to a `TreeSet` or `sort` method to easily get Z-A descending order." },
        { id: "jc-7-14", question: "If `a.equals(b)` is true, what is highly recommended regarding `a.compareTo(b)`?", options: ["It should return 1", "It should return -1", "It should return 0 (it should be consistent with equals)", "It doesn't matter"], answerIndex: 2, explanation: "If `compareTo` returns non-zero for equal objects, collections like `TreeSet` will behave erratically and violate the Set contract." },
        { id: "jc-7-15", question: "Can you sort a `HashSet`?", options: ["Yes, using HashSet.sort()", "Yes, using Collections.sort()", "No, Sets are unordered. You must convert it to a List or TreeSet first.", "Only if it has Strings"], answerIndex: 2, explanation: "The `sort` method only works on `List` structures because sorting requires positional indexing." },
        { id: "jc-7-16", question: "What does `Arrays.asList(1, 2, 3)` return?", options: ["A standard java.util.ArrayList", "A fixed-size list backed by the specified array", "A LinkedList", "An array"], answerIndex: 1, explanation: "You can modify elements (`set()`), but you CANNOT add or remove elements, as the underlying array cannot be resized." },
        { id: "jc-7-17", question: "What happens if you sort an array of primitives using `Arrays.sort(int[])` vs an array of Objects `Arrays.sort(Object[])`?", options: ["They use the same algorithm", "Primitives use a Dual-Pivot Quicksort (unstable); Objects use Timsort (stable)", "Primitives use Timsort", "Objects cannot be sorted"], answerIndex: 1, explanation: "Since primitive values (like two `5`s) are indistinguishable, stability is meaningless for them, so Java uses a faster, unstable Quicksort." },
        { id: "jc-7-18", question: "Which method in the `Collections` class performs a fast search on a SORTED list?", options: ["Collections.find()", "Collections.search()", "Collections.binarySearch()", "Collections.indexOf()"], answerIndex: 2, explanation: "Binary search provides O(log n) performance but requires the list to be strictly sorted first." },
        { id: "jc-7-19", question: "What happens if you run `Collections.binarySearch()` on an unsorted list?", options: ["It sorts the list first automatically", "It performs a linear search instead", "The results are undefined and completely unpredictable", "It throws an UnsortedException"], answerIndex: 2, explanation: "The algorithm makes assumptions based on order. Without it, the search will likely fail to find an existing element." },
        { id: "jc-7-20", question: "What does `binarySearch` return if the element is NOT found?", options: ["-1", "A negative integer representing the insertion point (-(insertion point) - 1)", "0", "null"], answerIndex: 1, explanation: "This tells you exactly where you *should* insert the element to keep the list sorted." }
